-- Sponsored Sweeps (#48, ADR 0010). Generated by drizzle-kit; the comments
-- are added by hand.
--
-- When the Provider's wallet signs a NEP-366 delegate action holding the
-- Sweep's MPC `sign` call, Herald's NEAR relayer sends it and pays the gas.
-- `near_tx_hash` is then the relayer's transaction, which NEAR RPC's `tx`
-- reads with the relayer as `sender_account_id`: this column names that
-- relayer. Null for every existing row and every Sweep the Provider's
-- wallet signed and paid for itself.
ALTER TABLE `sweeps` ADD `near_tx_relayer` text;
